import { test, expect } from '@playwright/test';

test.describe('Comment on Record', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully submit a comment on a record', async ({ page }) => {
    // Verify the records list is visible
    const recordsList = page.getByRole('region', { name: /records/i });
    await expect(recordsList).toBeVisible();

    // Select a record to comment on
    const recordItem = page.getByRole('region', { name: /record 1/i });
    await expect(recordItem).toBeVisible();
    await recordItem.click();

    // Verify the record details are visible
    const recordDetails = page.getByRole('region', { name: /record 1 details/i });
    await expect(recordDetails).toBeVisible();

    // Fill out the comment form
    const commentInput = page.getByLabel('Comment');
    await expect(commentInput).toBeVisible();
    await commentInput.fill('Great product!');

    // Verify the comment textarea is visible and editable
    const commentTextarea = page.getByLabel('Comment');
    await expect(commentTextarea).toBeVisible();
    await expect(commentTextarea).toBeEditable();

    // Submit the comment
    const submitButton = page.getByRole('button', { name: /submit comment/i });
    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText(/comment submitted successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the comment is saved
    const commentList = page.getByRole('region', { name: /comments/i });
    await expect(commentList).toBeVisible();

    // Verify the comment appears in the list
    const commentItem = page.getByText('Great product!');
    await expect(commentItem).toBeVisible();
  });

  test('should display error when commenting on a non-existent record', async ({ page }) => {
    // Navigate to the records list
    const recordsList = page.getByRole('region', { name: /records/i });
    await expect(recordsList).toBeVisible();

    // Click on a non-existent record
    const nonExistentRecordItem = page.getByRole('region', { name: /record 999999999/i });
    await expect(nonExistentRecordItem).toBeVisible();
    await nonExistentRecordItem.click();

    // Verify error message appears
    const errorMessage = page.getByText(/record not found/i);
    await expect(errorMessage).toBeVisible();

    // Verify the comment form is still visible
    const commentInput = page.getByLabel('Comment');
    await expect(commentInput).toBeVisible();

    // Attempt to submit an empty comment
    const submitButton = page.getByRole('button', { name: /submit comment/i });
    await expect(submitButton).toBeVisible();
    await submitButton.click();

    // Verify error message persists
    await expect(errorMessage).toBeVisible();

    // Verify the comment list is still empty
    const commentList = page.getByRole('region', { name: /comments/i });
    await expect(commentList).toBeVisible();
    const commentItem = page.getByText('Great product!');
    await expect(commentItem).not.toBeVisible();
  });
});
